 System.Data.DataTable dt;

    System.Collections.Generic.List<object[]> trupi = new System.Collections.Generic.List<object[]>();

 private void ReportHeader1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
        {   
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);


      System.Data.DataTable dt = ((System.Data.DataSet)(this.DataSource)).Tables[0];
		System.Data.DataView view = new System.Data.DataView(dt);
          System.Data.DataTable aprovuesit = view.ToTable(true, "aprovimPERSHKRIMI", "Aprovuesi", "DateAprovimi", "SASIA", "NIVELI", "KOMENT");

            trupi.Clear();	
            for (int i = 0; i < aprovuesit.Rows.Count; i++)
            {
         object PERSHKRIMI = dt.Rows[i]["aprovimPERSHKRIMI"]; 
                object Aprovuesi= dt.Rows[i]["Aprovuesi"]; 
                object DateAprovimi= dt.Rows[i]["DateAprovimi"];
                object SASIA = dt.Rows[i]["SASIA"];
                 object NIVELI = dt.Rows[i]["NIVELI"];
                 object KOMENT= dt.Rows[i]["KOMENT"];


               object[] obj = new object[7];

                obj[0] = (i + 1).ToString();
                obj[1] = PERSHKRIMI;
                obj[2] = Aprovuesi;
                obj[3] = DateAprovimi;
                obj[4] = SASIA ;
                obj[5] = NIVELI;
               obj[6] = KOMENT;
           trupi.Add(obj);
 }

            foreach (System.Data.DataRow dr in dt.Rows)
            {
                string niveliUserit = dr["aprovimPERSHKRIMI"].ToString();
                if (niveliUserit.ToLower()=="finance department only")
                {
                    xrLabel62.Text = dr["Aprovuesi"].ToString();
                    xrLabel64.Text = "DATE";
                    xrLabel65.Text = Convert.ToDateTime(dr["DateAprovimi"]).ToString("dd/MM/yyyy") ;
			  xrTableCell51.Text=dr["KOMENT"].ToString();

                }
                else if (niveliUserit.ToLower() == "purchasing dept. only")
                 {
                    xrLabel66.Text = dr["Aprovuesi"].ToString();
                    xrLabel68.Text = "DATE";
                    xrLabel69.Text = Convert.ToDateTime(dr["DateAprovimi"]).ToString("dd/MM/yyyy");
                 }

          }
 }



  private void shtoRreshtatNeTabele(XRTable xrTable8)
        {
            int i = 0;
            if (trupi.Count > 0)
            {

                for (int j = xrTable8.Rows.Count - 1; j >= 1; j--)
                {
                    xrTable8.Rows.RemoveAt(j);
                }
                Font arial = new Font("Times New Roman", 9.00F, FontStyle.Regular);
                PaddingInfo padding = new PaddingInfo(2, 2, 0, 0);
                DevExpress.XtraPrinting.BorderSide borders = ((DevExpress.XtraPrinting.BorderSide)(((DevExpress.XtraPrinting.BorderSide.Left | DevExpress.XtraPrinting.BorderSide.Top))));
                foreach (object[] obj in trupi)

                {
	 			if  ( obj[2].ToString()  == "" )
					return;


                    borders = ((DevExpress.XtraPrinting.BorderSide)(((DevExpress.XtraPrinting.BorderSide.Left | DevExpress.XtraPrinting.BorderSide.Top))));
                    XRTableRow rr = new XRTableRow();
                    rr.HeightF = 20f;
                    double vlerefatura = Convert.ToDouble(Report.GetCurrentColumnValue("TOTALI").ToString());
                    double kursi = Convert.ToDouble(Report.GetCurrentColumnValue("KURSIVF").ToString());
			  string pershkriminivelit = obj[1].ToString();
			  string kodiMonedhes = Report.GetCurrentColumnValue("MONEDHAKOD").ToString();
                    if ((vlerefatura/kursi < 5000 && pershkriminivelit.ToLower() == "ceo" && kodiMonedhes.ToLower()=="lek") || (vlerefatura < 5000 && pershkriminivelit.ToLower() == "ceo" && kodiMonedhes.ToLower() == "eur" ) || ( pershkriminivelit.ToLower()== "finance department only") || ( pershkriminivelit.ToLower() == "purchasing dept. only"))
                       continue;
                    XRTableCell pershkrimi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(84.8F, "", obj[1].ToString(), arial, Color.Black, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                    rr.Cells.Add(pershkrimi);
                    XRTableCell Aprovuesi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(93.9f, "", obj[2].ToString(), arial, Color.Black, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                    Aprovuesi.TextAlignment = DevExpress.XtraPrinting.TextAlignment.TopCenter;
				    rr.Cells.Add(Aprovuesi);
				Aprovuesi.Font =  new Font(Aprovuesi.Font.FontFamily, Aprovuesi.Font.Size, FontStyle.Bold);
                   string date = Convert.ToDateTime(obj[3]).ToString("dd/MM/yyyy");
                    XRTableCell DateAprovimi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(76.3F, "", date, arial, Color.Black,Color.Transparent,TextAlignment.MiddleRight, borders, padding);
                    DateAprovimi.TextAlignment = DevExpress.XtraPrinting.TextAlignment.TopCenter;
			  DateAprovimi.Font =  new Font(DateAprovimi.Font.FontFamily, DateAprovimi.Font.Size, FontStyle.Bold);

                    rr.Cells.Add(DateAprovimi);
                    borders = ((DevExpress.XtraPrinting.BorderSide)(((DevExpress.XtraPrinting.BorderSide.Left | DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Right))));
                    XRTableCell BOSH = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(68F, "", "Approved", arial, Color.Black, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                    rr.Cells.Add(BOSH);

                    xrTable8.Rows.Insert((i + 1), rr);
                    i++;
                }
            }
        }


private void xrLabel25_BeforePrint(object sender, PrintEventArgs e)
        {
         xrLabel25.Text=Report.GetCurrentColumnValue("KODKONFIGAMBJENTE").ToString();

        }
private void xrTable8_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
shtoRreshtatNeTabele(xrTable8);

}

private void detailBand1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 if (GetCurrentColumnValue("RowNumber") != null && GetCurrentColumnValue("RowNumber").ToString() != "1")
                e.Cancel = true;

}
    double shumaVLEFTAPATVSH = 0.00;
private void xrTableCell69_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrTableCell69.Text = String.Format("{0:n2}", GetCurrentColumnValue("VLEFTAPATVSH")).ToString();
shumaVLEFTAPATVSH  +=  Convert.ToDouble(xrTableCell69.Text);

}

private void xrLabel39_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrLabel39.Text = String.Format("{0:n2}", shumaVLEFTAPATVSH).ToString();

}
